  var MARKUP = "<div class=\"launcher-wrap\">\n  <button class=\"launcher\" id=\"launcher\" aria-label=\"Chat with Matilda\" aria-haspopup=\"dialog\">\n    <span class=\"status-dot\"></span>\n    <span class=\"k-avatar k-sleep\" id=\"launcherAvatar\"><img class=\"koala-img\" alt=\"\"><span class=\"spark\">\u2728</span></span>\n  </button>\n  <span class=\"tooltip\">Psst \u2014 ask Matilda \ud83d\udc28</span>\n</div>\n\n<section class=\"panel\" id=\"panel\" role=\"dialog\" aria-modal=\"false\" aria-label=\"Matilda assistant\">\n  <div class=\"p-head\">\n    <span class=\"k-avatar k-awake\" id=\"headAvatar\"><img class=\"koala-img\" alt=\"\"><span class=\"spark\">\u2728</span></span>\n    <div class=\"who\">\n      <strong>Matilda</strong>\n      <span id=\"statusText\">Online \u00b7 usually replies instantly</span>\n    </div>\n    <button class=\"x\" id=\"closeBtn\" aria-label=\"Close chat\">\u00d7</button>\n  </div>\n  <div class=\"p-log\" id=\"log\" role=\"log\" aria-live=\"polite\"></div>\n  <form class=\"p-comp\" id=\"form\">\n    <label for=\"input\" style=\"position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)\">Message Matilda</label>\n    <input type=\"text\" id=\"input\" placeholder=\"Ask me anything\u2026\" autocomplete=\"off\">\n    <button type=\"submit\" id=\"sendBtn\" aria-label=\"Send\">\u27a4</button>\n  </form>\n  <div class=\"p-foot\">Automated helper \u00b7 not NDIS advice \u00b7 Emergency? Call 000</div>\n</section>";

