const log=__root.getElementById('log');
const form=__root.getElementById('form');
const input=__root.getElementById('input');
const sendBtn=__root.getElementById('sendBtn');
const launcher=__root.getElementById('launcher');
const launcherAvatar=__root.getElementById('launcherAvatar');
const headAvatar=__root.getElementById('headAvatar');
const panel=__root.getElementById('panel');
const closeBtn=__root.getElementById('closeBtn');
const statusText=__root.getElementById('statusText');

let busy=false, opened=false, typingRow=null;

/* ---------- koala state machine ---------- */
function setKoala(state){
  [launcherAvatar, headAvatar].forEach(el=>{
    el.classList.remove('k-sleep','k-wake','k-awake','k-typing','k-reply');
    el.classList.add('k-'+state);
    const vid = el.querySelector('video.k-vid-'+state);
    if(vid){ vid.currentTime = 0; vid.play().catch(()=>{}); }
  });
  statusText.textContent = state==='typing' ? 'Matilda is typing…' : 'Online · usually replies instantly';
  statusText.className = state==='typing' ? 'busy' : '';
}

function showTypingRow(){
  typingRow=document.createElement('div');
  typingRow.className='msg bot';
  typingRow.innerHTML='<div class="typing-row"><i></i><i></i><i></i></div>';
  log.appendChild(typingRow);
  log.scrollTop=log.scrollHeight;
}
function hideTypingRow(){ if(typingRow){ typingRow.remove(); typingRow=null; } }

function add(html, who, alert, quick){
  const d=document.createElement('div');
  d.className='msg '+who;
  const b=document.createElement('div');
  b.className='bubble'+(alert?' alert':'');
  if(alert){ b.style.background='rgba(220,38,38,.16)'; b.style.borderColor='#DC2626'; }
  b.innerHTML=html;
  d.appendChild(b);
  if(quick && quick.length){
    const box=document.createElement('div');
    box.className='quick';
    quick.forEach(q=>{
      const btn=document.createElement('button');
      btn.className='chip'; btn.type='button'; btn.textContent=q.label;
      btn.addEventListener('click',()=>{
        if(busy) return;
        busy=true; sendBtn.disabled=true;
        add(q.label,'me');
        setKoala('typing'); showTypingRow();
        setTimeout(()=>{
          hideTypingRow();
          runIntent(q.id, q.label);
          setKoala('reply');
          setTimeout(()=>setKoala('awake'),1500);
          busy=false; sendBtn.disabled=false;
        }, 420);
      });
      box.appendChild(btn);
    });
    d.appendChild(box);
  }
  log.appendChild(d);
  log.scrollTop=log.scrollHeight;
}

let pending=null;
function say(intent, text){
  add(intent.reply(text||''),'bot',intent.alert,intent.quick);
  pending = intent.yes || null;
}
function runIntent(id, text){
  const i = INTENTS.find(x=>x.id===id);
  if(i) say(i, text);
  else { add("Here's what I know well — tap whichever is closest:","bot",false,FALLBACK_QUICK); pending=null; }
}

const AFFIRM = /^\s*(y|ya|yes|yeah|yep|yup|sure|ok|okay|please|yes please|go on|go ahead|do it|alright|right|sounds good|that would (be )?(good|great|help)|thatd be good|absolutely|definitely|why not|👍)\b/i;
const DECLINE = /^\s*(n|no|nah|nope|no thanks|not now|not really|maybe later|i'?m good)\b/i;

const STEM = {finding:'find',posting:'post',applying:'apply',registering:'register',
  appealing:'appeal',complaining:'complain',cancelling:'cancel',canceling:'cancel',
  getting:'get',making:'make',asking:'ask',looking:'look',browsing:'browse',
  searching:'search',updating:'update',understanding:'understand',choosing:'choose',
  hiring:'hire',paying:'pay',talking:'talk',speaking:'speak'};

function normalise(t){
  return t.toLowerCase()
    .replace(/\b(\w+ing)\b/g,(m,w)=>STEM[w]||m)
    .replace(/[?!.,]+/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function respond(text){
  const t = normalise(text);
  if(pending && AFFIRM.test(t)){ const p=pending; pending=null; runIntent(p, text); return; }
  if(pending && DECLINE.test(t)){
    pending=null;
    add(`No worries at all. Anything else I can help with?`,'bot',false,FALLBACK_QUICK);
    return;
  }
  let best=null, score=0;
  for(const i of INTENTS){
    if((i.pat.test(t) || i.pat.test(text)) && i.weight>score){ best=i; score=i.weight; }
  }
  if(best){ say(best, text); return; }
  if(AFFIRM.test(t) || DECLINE.test(t)){
    add(`Sorry — I've lost track of what that's answering. Here's what I can help with:`,'bot',false,FALLBACK_QUICK);
    pending=null; return;
  }
  const soft = softMatch(t);
  if(soft){ runIntent(soft, text); return; }
  add(catchAll(text),'bot',false,FALLBACK_QUICK);
  pending=null;
}

function send(text){
  const msg = String(text==null?input.value:text).trim();
  if(!msg || busy) return;
  busy=true; sendBtn.disabled=true;
  add(msg.replace(/</g,'&lt;'),'me');
  input.value='';
  setKoala('typing');
  showTypingRow();
  const delay = 380 + Math.min(650, msg.length*10);
  setTimeout(()=>{
    hideTypingRow();
    respond(msg);
    setKoala('reply');
    setTimeout(()=>setKoala('awake'),1500);
    busy=false; sendBtn.disabled=false; input.focus();
  }, delay);
}

form.addEventListener('submit', e=>{ e.preventDefault(); send(); });

/* ---------- launcher / panel open-close ---------- */
function openPanel(){
  setKoala('wake');
  setTimeout(()=>{
    panel.classList.add('open');
    setKoala('awake');
    if(!opened){
      opened=true;
      add(`Oi oi, I'm <strong>Matilda</strong> — the assistant with more attitude than a koala woken up mid-nap, and zero patience for red tape.

I can sort you a provider, help you post a request, explain your rights, or point you round this joint. Ask away, I don't bite (much).

What are we cracking into first?`, 'bot', false, GREETING_QUICK);
    }
    input.focus();
  }, 950);
}
function closePanel(){
  panel.classList.remove('open');
  setKoala('sleep');
}
launcher.addEventListener('click', ()=>{
  if(panel.classList.contains('open')) closePanel(); else openPanel();
});
closeBtn.addEventListener('click', closePanel);
document.addEventListener('keydown', e=>{
  if(e.key==='Escape' && panel.classList.contains('open')) closePanel();
});

